            /** Content */
            content: string | null;
            /**
             * Created At
             * Format: date-time
             */
            created_at: string;
            /** Importance */
            importance: number | null;
            /** Kind */
            kind: string;
            /**
             * Memory Id
             * Format: uuid
             */
            memory_id: string;
            /** Scope */
            scope: string;
            /** Scope Ref */
            scope_ref: string | null;
            /**
             * State
             * @enum {string}
             */
            state: "live" | "superseded" | "tombstoned" | "expired";
            /** Superseded By */
            superseded_by: string | null;
            /**
             * Tenant Id
             * Format: uuid
             */
            tenant_id: string;
            /** Title */
            title: string | null;
            /** Valid Until */
            valid_until: string | null;
