                secret_finding_kind?: string | null;
                /** @description true = the detector ran (kinds is non-NULL, possibly empty); false = it never ran. The two are deliberately distinct: an unscanned row is not a clean one. */
                detector_ran?: boolean | null;
                /** @description Only sessions with last_activity_at at/after this timestamp. A row with no recorded activity is excluded. */
